public final class LoadBalancer {
    private static final List<Server> servers = new ArrayList<>();
    private static int nextIndex = 0;          // shared static state

    public void serve(Request r) {             // ordinary instance method
        servers.get(nextIndex).serve(r);
        nextIndex = (nextIndex + 1) % servers.size();
    }
    public LoadBalancer() {                    // every instance joins the pool
        servers.add(new Server("10.0.0.1", 8080));
    }
}
